    ds = js("const out=[]; for(let i=1;i<=8;i++){ const x=G.generate(500+i*91,{distress:true}); if(x) out.push({r:x.def.gen.reason,nm:Math.round(sim.s.lat?0:0)+1, h:x.def.gen.routeH, dl:x.offer.deadlineH, ex:x.offer.expiresH, urg:x.def.gen.urgency, comp:x.def.gen.compulsory}); } return out")
    check("distress offers: distress urgency, optional, margin over the route", ds and all(x["urg"] == "distress" and not x["comp"] and x["dl"] >= x["h"] * 1.2 and x["r"] in ("sinking", "survivors", "disabled_ship", "disabled_sub") for x in ds), str(ds[:2]))
    js("G.makeOffer({type:'survey',compulsory:true}); for(let i=0;i<10;i++) sim.step(6); G.acceptOffer(gameState.getProperty('mission.gen').offer.id)")
