    js("G.acceptOffer(gameState.getProperty('mission.gen').offer.id)")
    after = js("const g=gameState.getProperty('mission.gen'); return {active:g.active, d:g.defs[g.active]&&g.defs[g.active].gen.distress, oera:Rp.rep('oera')}")
    check("accepting it breaks away from the compulsory mission with no OERA penalty", after["d"] is True and abs(after["oera"] - oera0) < 0.05, str(after) + f" {oera0}")
    did = js("const g=gameState.getProperty('mission.gen'); g.offerAccepted.deadlineAt=sim.s.clock+10; sim.s.clock+=3600; sim.step(6); sim.step(6); return {active:g.active, last:g.done.slice(-1)[0]}")
    check("past the deadline and not on scene: too late", did["active"] is None and did["last"]["outcome"] == "too_late", str(did))
    js("const g=gameState.getProperty('mission.gen'); g.nextAt=null; g.offer=null; g.active=null; g.held=null")
    js("G.makeOffer({distress:true,reason:'sinking'}); G.acceptOffer(gameState.getProperty('mission.gen').offer.id); const g=gameState.getProperty('mission.gen'); const v=g.vessels[0]; sim.s.lat=v.A.lat+0.02; sim.s.lon=v.A.lon; sim.step(6); sim.step(6); g.offerAccepted.deadlineAt=sim.s.clock+10; sim.s.clock+=3600; sim.step(6); sim.step(6);")
    check("on scene before the deadline: not too late", js("return gameState.getProperty('mission.gen').active") is not None)
    civ = js("return Rp.rep('civil')")
