    c0 = js("const v=gameState.getProperty('mission.gen').vessels[0]; return {c:v.casualty, brief:v.casualty.started}")
    check("choosing to rescue starts the casualty clock with survivors waiting", c0["brief"] and c0["c"]["waiting"] >= 3 and c0["c"]["endsAt"] > 0, str(c0))
    ride = "const v=gameState.getProperty('mission.gen').vessels[0], B=await import('./js/bayops.js'); const sh=B.shuttle(); Object.assign(sh,{state:'out',mode:'station',lat:%s,lon:v.A.lon,depth:%s,pilots:2,pax:sh.pax||0,o2:100,bat:100,moving:false}); for(let i=0;i<9;i++){ sim.s.clock+=10; sim.step(0.1); } return {c:v.casualty, pax:sh.pax}"
    far = js(ride % ("v.A.lat+0.05", "0"))
    check("a Tern that is not alongside takes no one", far["c"]["aboard"] == 0, str(far))
