    first = near["c"]["aboard"]
    js("const B=await import('./js/bayops.js'); const sh=B.shuttle(); sh.state='bay'; sim.s.clock+=10; sim.step(0.1); sim.step(0.1)")
    sv = js("const v=gameState.getProperty('mission.gen').vessels[0]; return {saved:v.casualty.saved, aboard:v.casualty.aboard, wait:v.casualty.waiting, pax:(await import('./js/bayops.js')).shuttle().pax}")
    check("landing them in the bay saves them and empties the Tern", sv["saved"] == first and sv["aboard"] == 0 and sv["pax"] == 0, str(sv))
    for _ in range(4):
        if js("return gameState.getProperty('mission.gen').vessels[0].casualty.waiting") == 0: break
        js(ride % ("v.A.lat", "0")); js("const B=await import('./js/bayops.js'); B.shuttle().state='bay'; sim.s.clock+=10; sim.step(0.1); sim.step(0.1)")
    js("document.dispatchEvent(new CustomEvent('report-sent')); sim.step(6)")
    done = js("const g=gameState.getProperty('mission.gen'); return {last:g.done.slice(-1)[0]}")
    check("everyone saved ends as a full rescue", done["last"]["outcome"] == "assist_rescue", str(done))
    check("a rescue raises civil standing", js("return Rp.rep('civil')") > civ)
    # time runs out: survivors not reached are lost, honest outcome
    js("const g=gameState.getProperty('mission.gen'); g.nextAt=null; g.offer=null; g.active=null; g.held=null; sim.s.depth=5; sim.s.targetDepth=5")
    js("G.makeOffer({distress:true,reason:'survivors'}); G.acceptOffer(gameState.getProperty('mission.gen').offer.id); const v=gameState.getProperty('mission.gen').vessels[0]; sim.s.lat=v.A.lat+0.02; sim.s.lon=v.A.lon; for(let i=0;i<4;i++) sim.step(6); v.ident=true; for(let i=0;i<4;i++){ sim.s.clock+=10; sim.step(6);} ")
    js("const d=gameState.getProperty('progress.decisions').pending[0]; const a=await import('./js/aria.js'); a.decide(d.id,'assist'); sim.step(6); sim.step(6); const v=gameState.getProperty('mission.gen').vessels[0]; sim.s.clock=v.casualty.endsAt+60; sim.step(6); sim.step(6)")
    lost = js("const g=gameState.getProperty('mission.genFlags'); const id=gameState.getProperty('mission.gen').active; return {o:g[id].outcome, active:id}")
    check("nobody reached before the air runs out is an honest 'none' outcome", lost["o"] == "rescue_none", str(lost))
    js("document.dispatchEvent(new CustomEvent('report-sent')); sim.step(6)")
