    pr = js("const r=G.makeOffer({type:'patrol',compulsory:false}); for(let i=0;i<10;i++) sim.step(6); const g=gameState.getProperty('mission.gen'); const m=(gameState.getProperty('mission.inbox')||[]).find(x=>x.id==='offer-'+g.offer.id); return r&&{id:r.def.id, dur:g.offer.durH, start:g.offer.startAt, end:g.offer.endAt, text:m.text}")
    check("a patrol offer carries a window and a duration of 12 or 24 h", pr and pr["dur"] in (12, 24) and pr["end"] - pr["start"] == pr["dur"] * 3600 and "On station from" in pr["text"], str(pr and {k: v for k, v in pr.items() if k != 'text'}))
    if pr:
        js(f"G.acceptOffer('{pr['id']}')")
        check("accepting draws the temporary AO", js("return (sim.tempAOs||[]).length") == 1)
        js("const a=sim.tempAOs[0]; sim.s.lat=a.lat; sim.s.lon=a.lon; sim.step(6); sim.step(6)")
        check("entering the area completes the first objective", js("return (gameState.getProperty('mission.objectives')||[]).find(o=>o.id.endsWith('_arrive')).status") == "completed")
        js("const a=sim.tempAOs[0]; sim.s.clock=a.from; for(let i=0;i<(3.2*3600)/100;i++){ sim.s.clock+=100; sim.step(0.1) }")
        check("poachers appear in the area after the window opens", js("return gameState.getProperty('mission.gen').vessels.length") >= 1)
        js("const g=gameState.getProperty('mission.gen'); const v=g.vessels[0]; sim.s.lat=v.A.lat+0.01; sim.s.lon=v.A.lon; sim.step(6); sim.step(6); g.vessels[0].ident=true; sim.s.clock+=10; sim.step(6); sim.s.clock+=10; sim.step(6)")
        check("identifying one puts a warn-off decision", js("return (gameState.getProperty('progress.decisions')||{pending:[]}).pending.length") >= 1)
        poa = js("const rp=Rp; return Rp.rep('poachers')")
        js("const d=gameState.getProperty('progress.decisions').pending[0]; const a=await import('./js/aria.js'); a.decide(d.id,'warn_off'); const t=sim.tempAOs[0]; sim.s.lat=t.lat; sim.s.lon=t.lon; sim.step(6)")
        js("const a=sim.tempAOs[0]; while(sim.s.clock<a.to+300){ sim.s.clock+=100; sim.step(0.1) }")
