    js("const g=gameState.getProperty('mission.gen'); g.nextAt=null; g.offer=null; g.active=null; g.held=null; sim.s.depth=5; sim.s.targetDepth=5")
    js("const s=sim.s, c=s.pois.find(p=>p.type==='dock'); Object.assign(s,{lat:c.lat-0.3,lon:c.lon-0.1,speed:0,depth:5,targetDepth:5})")
    ok = js("const r=G.makeOffer({distress:true,reason:'disabled_sub'}); if(!r) return false; G.acceptOffer(r.def.id); const v=gameState.getProperty('mission.gen').vessels[0]; sim.s.lat=v.A.lat+0.02; sim.s.lon=v.A.lon; for(let i=0;i<4;i++) sim.step(6); v.ident=true; for(let i=0;i<4;i++){ sim.s.clock+=10; sim.step(6);} const d=gameState.getProperty('progress.decisions').pending[0]; const a=await import('./js/aria.js'); a.decide(d.id,'assist'); sim.step(6); sim.step(6); return v.casualty.mode+':'+v.casualty.depth")
